const interactiveDocTemplate = "# {{PROJECT_NAME}} \u4e92\u52a8 API \u6587\u6863\n\n## \u6587\u6863\u7528\u9014\n\u8fd9\u4efd\u6587\u6863\u662f\u7ed9 AI \u7528\u7684\u3002\u8bf7\u6839\u636e\u4e0b\u9762\u7684\u4f5c\u54c1\u4fe1\u606f\u3001\u8ba4\u8bc1\u65b9\u5f0f\u3001\u63a5\u53e3\u3001\u9519\u8bef\u7801\u548c\u73b0\u6709\u6570\u636e\u8868\uff0c\u4e3a\u8fd9\u4e2a\u4f5c\u54c1\u7f16\u5199\u4e92\u52a8\u529f\u80fd\u3002\n\n## \u91cd\u8981\u89c4\u5219\n- \u6240\u6709\u516c\u5f00\u4e92\u52a8 API \u8bf7\u6c42\u90fd\u5fc5\u987b\u5e26\u4e0a `X-Project-Key` \u8bf7\u6c42\u5934\u3002\n- API \u57fa\u7840\u5730\u5740\u56fa\u5b9a\u4f7f\u7528\u76f8\u5bf9\u8def\u5f84\uff1a`/api/v1/public/projects/{{PROJECT_ID}}`\u3002\u4e0d\u8981\u4f7f\u7528 'api.wangru.net'\uff0c\u4e5f\u4e0d\u8981\u81ea\u5df1\u731c\u6d4b\u5176\u4ed6 API \u57df\u540d\u3002\n- \u8bf7\u4f7f\u7528 UTF-8\uff0c\u5e76\u5728\u751f\u6210\u7684 HTML \u4e2d\u52a0\u5165 `<meta charset=\"utf-8\">`\u3002\n- \u5224\u65ad\u63a5\u53e3\u9519\u8bef\u65f6\uff0c\u8bf7\u4f18\u5148\u4f7f\u7528 HTTP \u72b6\u6001\u7801\uff0c\u4e0d\u8981\u53ea\u5224\u65ad\u82f1\u6587\u9519\u8bef\u6587\u672c\u3002\u5e73\u53f0\u9519\u8bef\u63d0\u793a\u662f\u4e2d\u6587\uff0c\u4f8b\u5982\u201c\u627e\u4e0d\u5230\u8fd9\u4e2a\u4f5c\u54c1\u6570\u636e\u8868\u201d\u3002\n- \u5982\u679c\u8bfb\u53d6\u5355\u4e2a\u6570\u636e\u8868\u8fd4\u56de HTTP `404`\uff0c\u8868\u793a\u8fd9\u4e2a\u6570\u636e\u8868\u4e0d\u5b58\u5728\uff0c\u53ef\u4ee5\u521b\u5efa\u6570\u636e\u8868\uff1b\u5982\u679c\u662f\u5176\u4ed6\u72b6\u6001\u7801\uff0c\u4e0d\u8981\u5f53\u6210\u6570\u636e\u8868\u4e0d\u5b58\u5728\u3002\n- \u5982\u679c\u8981\u5199\u5165\u7559\u8a00\u3001\u8bc4\u8bba\u3001\u8bba\u575b\u5e16\u5b50\u3001\u89d2\u8272\u6570\u636e\u3001\u5b58\u6863\u7b49\u5185\u5bb9\uff0c\u5148\u786e\u8ba4\u6570\u636e\u8868\u662f\u5426\u5b58\u5728\uff1b\u4e0d\u5b58\u5728\u65f6\u5148\u521b\u5efa\u6570\u636e\u8868\u3002\n- \u521b\u5efa\u6570\u636e\u8868\u4f1a\u53d7\u4f5c\u54c1\u5f53\u524d\u5957\u9910\u548c\u7528\u91cf\u9650\u5236\u5f71\u54cd\uff1b\u5982\u679c\u63a5\u53e3\u8fd4\u56de `429` \u6216\u989d\u5ea6\u76f8\u5173\u9519\u8bef\uff0c\u8bf7\u7528\u4e2d\u6587\u63d0\u793a\u7528\u6237\u51cf\u5c11\u6570\u636e\u8868\u3001\u51cf\u5c11\u64cd\u4f5c\u9891\u7387\u6216\u5347\u7ea7\u5957\u9910\uff0c\u4e0d\u8981\u7ed5\u8fc7\u9650\u5236\u3002\n- \u521b\u5efa\u6570\u636e\u8868\u5931\u8d25\u65f6\u4e0d\u8981\u53cd\u590d\u91cd\u8bd5\uff0c\u66f4\u4e0d\u8981\u5220\u9664\u3001\u6e05\u7a7a\u6216\u91cd\u5efa\u5df2\u6709\u6570\u636e\u8868\u3002\n- \u516c\u5f00\u63a5\u53e3\u4e0d\u5141\u8bb8\u5220\u9664\u6570\u636e\u8868\uff0c\u4e5f\u4e0d\u8981\u751f\u6210\u5220\u9664\u6570\u636e\u8868\u3001\u6e05\u7a7a\u6570\u636e\u8868\u6216\u91cd\u5efa\u6570\u636e\u8868\u7684\u4ee3\u7801\u3002\u5df2\u6709\u6570\u636e\u8868\u6ee1\u8db3\u9700\u6c42\u65f6\u5fc5\u987b\u590d\u7528\u3002\n- \u6743\u9650\u53ea\u4f7f\u7528 `publicRead` \u548c `publicWrite`\uff0c\u4e0d\u8981\u4f7f\u7528\u767b\u5f55\u7528\u6237\u3001\u521b\u4f5c\u8005\u6216\u6240\u6709\u8005\u4e13\u7528\u5199\u5165\u6743\u9650\u3002\n- \u5982\u679c\u8fd9\u4e2a\u6570\u636e\u8868\u9700\u8981\u8bbf\u5ba2\u901a\u8fc7\u7f51\u9875\u65b0\u589e\u3001\u7f16\u8f91\u6216\u5220\u9664\u8bb0\u5f55\uff0c\u521b\u5efa\u6570\u636e\u8868\u65f6\u5fc5\u987b\u8bbe\u7f6e `publicWrite: true`\u3002\u5982\u679c\u8bbe\u7f6e\u4e3a `false`\uff0c\u516c\u5f00\u7f51\u9875\u540e\u7eed\u5c06\u65e0\u6cd5\u5199\u5165\u3001\u4fee\u6539\u6216\u5220\u9664\u8fd9\u4e2a\u8868\u7684\u8bb0\u5f55\u3002\n- \u53ea\u6709\u7eaf\u5c55\u793a\u3001\u4e0d\u9700\u8981\u8bbf\u5ba2\u63d0\u4ea4\u6216\u4fee\u6539\u5185\u5bb9\u7684\u6570\u636e\u8868\uff0c\u624d\u5efa\u8bae\u8bbe\u7f6e `publicWrite: false`\u3002\n- \u65b0\u589e\u6216\u66f4\u65b0\u8bb0\u5f55\u65f6\uff0c\u4e1a\u52a1\u6570\u636e\u7edf\u4e00\u653e\u8fdb `data` \u5bf9\u8c61\u91cc\u3002\n- \u4e0d\u8981\u628a `X-Project-Key` \u4fdd\u5b58\u5230 `localStorage`\u3002\u5982\u679c\u5fc5\u987b\u5199\u8fdb\u9759\u6001\u7f51\u9875\uff0c\u53ea\u628a\u5b83\u4f5c\u4e3a\u5f53\u524d\u4f5c\u54c1\u7684\u516c\u5f00\u4e92\u52a8 key \u4f7f\u7528\u3002\n- \u7528\u6237\u70b9\u51fb\u6309\u94ae\u3001\u63d0\u4ea4\u8868\u5355\u7b49\u660e\u786e\u64cd\u4f5c\u540e\u624d\u53d1\u8d77\u5199\u5165\u8bf7\u6c42\uff0c\u4e0d\u8981\u56e0\u4e3a\u9875\u9762\u52a0\u8f7d\u3001\u9f20\u6807\u60ac\u505c\u6216\u8f93\u5165\u6846\u805a\u7126\u5c31\u5199\u5165\u6570\u636e\u3002\n\n## \u4f5c\u54c1\u4fe1\u606f\n- \u4f5c\u54c1 ID\uff1a`{{PROJECT_ID}}`\n- \u4f5c\u54c1\u540d\u79f0\uff1a{{PROJECT_NAME}}\n- \u4f5c\u54c1\u5730\u5740\uff1a{{PUBLIC_URL}}\n- \u4e92\u52a8\u529f\u80fd\uff1a\u5df2\u5f00\u542f\n\n## \u8ba4\u8bc1\u65b9\u5f0f\n\u6bcf\u4e2a\u516c\u5f00\u4e92\u52a8 API \u8bf7\u6c42\u90fd\u8981\u5e26\u4e0a\u8fd9\u4e2a\u8bf7\u6c42\u5934\uff1a\n```http\nX-Project-Key: {{PROJECT_KEY}}\n```\n\n## API \u57fa\u7840\u5730\u5740\n\u5728\u4f5c\u54c1\u9875\u9762\u91cc\u8c03\u7528\u63a5\u53e3\u65f6\uff0c\u8bf7\u4f7f\u7528\u8fd9\u4e2a\u76f8\u5bf9\u5730\u5740\u4f5c\u4e3a\u57fa\u7840\u5730\u5740\uff1a\n```js\nconst API_BASE = '/api/v1/public/projects/{{PROJECT_ID}}';\n```\n\u4e0d\u8981\u5199\u6210 `https://api.wangru.net/...`\u3002\u5982\u679c\u5fc5\u987b\u4f7f\u7528\u5b8c\u6574\u5730\u5740\uff0c\u8bf7\u4f7f\u7528\u5f53\u524d\u7f51\u7ad9\u57df\u540d\u52a0\u4e0a\u4e0a\u9762\u7684\u76f8\u5bf9\u8def\u5f84\u3002\n\n## \u63a5\u53e3\u5217\u8868\n- \u8bfb\u53d6\u4f5c\u54c1\u4fe1\u606f\uff1a`GET /api/v1/public/projects/{{PROJECT_ID}}`\n- \u8bfb\u53d6\u6570\u636e\u8868\u5217\u8868\uff1a`GET /api/v1/public/projects/{{PROJECT_ID}}/collections`\n- \u521b\u5efa\u6570\u636e\u8868\uff1a`POST /api/v1/public/projects/{{PROJECT_ID}}/collections`\n- \u8bfb\u53d6\u5355\u4e2a\u6570\u636e\u8868\uff1a`GET /api/v1/public/projects/{{PROJECT_ID}}/collections/{collectionName}`\n- \u8bfb\u53d6\u8bb0\u5f55\u5217\u8868\uff1a`GET /api/v1/public/projects/{{PROJECT_ID}}/collections/{collectionName}/records`\n- \u521b\u5efa\u8bb0\u5f55\uff1a`POST /api/v1/public/projects/{{PROJECT_ID}}/collections/{collectionName}/records`\n- \u8bfb\u53d6\u5355\u6761\u8bb0\u5f55\uff1a`GET /api/v1/public/projects/{{PROJECT_ID}}/collections/{collectionName}/records/{recordId}`\n- \u66f4\u65b0\u8bb0\u5f55\uff1a`PATCH /api/v1/public/projects/{{PROJECT_ID}}/collections/{collectionName}/records/{recordId}`\n- \u5220\u9664\u8bb0\u5f55\uff1a`DELETE /api/v1/public/projects/{{PROJECT_ID}}/collections/{collectionName}/records/{recordId}`\n\n## \u63a5\u53e3\u54cd\u5e94\u793a\u4f8b\n### \u8bfb\u53d6\u4f5c\u54c1\u4fe1\u606f\uff1aGET /api/v1/public/projects/{{PROJECT_ID}}\n```json\n{\n  \"project\": {\n    \"id\": \"{{PROJECT_ID}}\",\n    \"name\": \"{{PROJECT_NAME}}\",\n    \"publicUrl\": \"{{PUBLIC_URL}}\",\n    \"interactive\": true\n  }\n}\n```\n\n### \u8bfb\u53d6\u6570\u636e\u8868\u5217\u8868\uff1aGET /api/v1/public/projects/{{PROJECT_ID}}/collections\n```json\n{\n  \"projectId\": \"{{PROJECT_ID}}\",\n  \"items\": [\n    {\n      \"id\": \"collection-id\",\n      \"projectId\": \"{{PROJECT_ID}}\",\n      \"name\": \"posts\",\n      \"permissions\": {\n        \"publicRead\": true,\n        \"publicWrite\": true\n      },\n      \"fields\": [\n        {\n          \"name\": \"title\",\n          \"type\": \"string\",\n          \"required\": true,\n          \"isList\": false\n        },\n        {\n          \"name\": \"content\",\n          \"type\": \"text\",\n          \"required\": true,\n          \"isList\": false\n        }\n      ],\n      \"createdAt\": \"2026-01-01T00:00:00Z\"\n    }\n  ]\n}\n```\n\n### \u521b\u5efa\u6570\u636e\u8868\uff1aPOST /api/v1/public/projects/{{PROJECT_ID}}/collections\n```json\n{\n  \"id\": \"collection-id\",\n  \"projectId\": \"{{PROJECT_ID}}\",\n  \"name\": \"posts\",\n  \"permissions\": {\n    \"publicRead\": true,\n    \"publicWrite\": true\n  },\n  \"fields\": [\n    {\n      \"name\": \"title\",\n      \"type\": \"string\",\n      \"required\": true,\n      \"isList\": false\n    },\n    {\n      \"name\": \"content\",\n      \"type\": \"text\",\n      \"required\": true,\n      \"isList\": false\n    }\n  ],\n  \"createdAt\": \"2026-01-01T00:00:00Z\"\n}\n```\n\n### \u8bfb\u53d6\u5355\u4e2a\u6570\u636e\u8868\uff1aGET /api/v1/public/projects/{{PROJECT_ID}}/collections/{collectionName}\n\u54cd\u5e94\u683c\u5f0f\u548c\u521b\u5efa\u6570\u636e\u8868\u8fd4\u56de\u683c\u5f0f\u76f8\u540c\u3002\u5982\u679c\u6570\u636e\u8868\u4e0d\u5b58\u5728\uff0c\u4f1a\u8fd4\u56de HTTP `404`\u3002\n\n### \u8bfb\u53d6\u8bb0\u5f55\u5217\u8868\uff1aGET /api/v1/public/projects/{{PROJECT_ID}}/collections/{collectionName}/records\n```json\n{\n  \"projectId\": \"{{PROJECT_ID}}\",\n  \"collectionName\": \"posts\",\n  \"items\": [\n    {\n      \"id\": \"record-id\",\n      \"projectId\": \"{{PROJECT_ID}}\",\n      \"collectionId\": \"collection-id\",\n      \"data\": {\n        \"title\": \"\u793a\u4f8b\u6807\u9898\",\n        \"content\": \"\u793a\u4f8b\u5185\u5bb9\"\n      },\n      \"status\": \"active\",\n      \"createdAt\": \"2026-01-01T00:00:00Z\",\n      \"updatedAt\": \"2026-01-01T00:00:00Z\"\n    }\n  ]\n}\n```\n\n### \u521b\u5efa\u8bb0\u5f55\uff1aPOST /api/v1/public/projects/{{PROJECT_ID}}/collections/{collectionName}/records\n### \u8bfb\u53d6\u5355\u6761\u8bb0\u5f55\uff1aGET /api/v1/public/projects/{{PROJECT_ID}}/collections/{collectionName}/records/{recordId}\n### \u66f4\u65b0\u8bb0\u5f55\uff1aPATCH /api/v1/public/projects/{{PROJECT_ID}}/collections/{collectionName}/records/{recordId}\n\u4ee5\u4e0a\u4e09\u4e2a\u63a5\u53e3\u90fd\u4f1a\u8fd4\u56de\u5355\u6761\u8bb0\u5f55\uff0c\u683c\u5f0f\u5982\u4e0b\uff1a\n```json\n{\n  \"id\": \"record-id\",\n  \"projectId\": \"{{PROJECT_ID}}\",\n  \"collectionId\": \"collection-id\",\n  \"data\": {\n    \"title\": \"\u793a\u4f8b\u6807\u9898\",\n    \"content\": \"\u793a\u4f8b\u5185\u5bb9\"\n  },\n  \"status\": \"active\",\n  \"createdAt\": \"2026-01-01T00:00:00Z\",\n  \"updatedAt\": \"2026-01-01T00:00:00Z\"\n}\n```\n\n### \u5220\u9664\u8bb0\u5f55\uff1aDELETE /api/v1/public/projects/{{PROJECT_ID}}/collections/{collectionName}/records/{recordId}\n```json\n{\n  \"status\": \"deleted\"\n}\n```\n\n## \u9519\u8bef\u7801\u548c\u9519\u8bef\u54cd\u5e94\u793a\u4f8b\n\u516c\u5f00\u4e92\u52a8\u63a5\u53e3\u51fa\u9519\u65f6\u901a\u5e38\u8fd4\u56de JSON\uff0c\u91cc\u9762\u6709 `error` \u5b57\u6bb5\u3002\u8bf7\u628a `error` \u5b57\u6bb5\u4f5c\u4e3a\u4e2d\u6587\u63d0\u793a\u5c55\u793a\u7ed9\u7528\u6237\uff0c\u4f46\u4e1a\u52a1\u5224\u65ad\u8981\u4f18\u5148\u770b HTTP \u72b6\u6001\u7801\u3002\n\n### HTTP 400\uff1a\u8bf7\u6c42\u5185\u5bb9\u6216\u4f5c\u54c1\u72b6\u6001\u4e0d\u6b63\u786e\n\u5e38\u89c1\u4e8e\u4f5c\u54c1\u6ca1\u6709\u542f\u7528\u4e92\u52a8\u529f\u80fd\u3001JSON \u683c\u5f0f\u4e0d\u6b63\u786e\u3001\u6570\u636e\u8868\u540d\u4e3a\u7a7a\u3001\u8bb0\u5f55\u5185\u5bb9\u4e3a\u7a7a\u7b49\u60c5\u51b5\u3002\n```json\n{\n  \"error\": \"\u8bf7\u6c42\u5185\u5bb9\u683c\u5f0f\u4e0d\u6b63\u786e\"\n}\n```\n```json\n{\n  \"error\": \"\u8fd9\u4e2a\u4f5c\u54c1\u6ca1\u6709\u542f\u7528\u4e92\u52a8\u529f\u80fd\"\n}\n```\n\n### HTTP 401\uff1a\u4f5c\u54c1\u6570\u636e\u5bc6\u94a5\u4e0d\u6b63\u786e\n\u5e38\u89c1\u4e8e\u6ca1\u6709\u4f20 `X-Project-Key`\uff0c\u6216\u4f20\u5165\u7684 key \u4e0d\u5c5e\u4e8e\u8fd9\u4e2a\u4f5c\u54c1\u3002\n```json\n{\n  \"error\": \"\u4f5c\u54c1\u6570\u636e\u5bc6\u94a5\u4e0d\u6b63\u786e\"\n}\n```\n\n### HTTP 403\uff1a\u5f53\u524d\u516c\u5f00\u6743\u9650\u4e0d\u5141\u8bb8\u8fd9\u4e2a\u64cd\u4f5c\n\u5e38\u89c1\u4e8e\u8bfb\u53d6 `publicRead: false` \u7684\u6570\u636e\u8868\u3001\u5199\u5165 `publicWrite: false` \u7684\u6570\u636e\u8868\uff0c\u6216\u5c1d\u8bd5\u901a\u8fc7\u516c\u5f00\u63a5\u53e3\u5220\u9664\u6570\u636e\u8868\u3002\n```json\n{\n  \"error\": \"\u8fd9\u4e2a\u4f5c\u54c1\u6570\u636e\u8868\u4e0d\u5141\u8bb8\u516c\u5f00\u8bfb\u53d6\"\n}\n```\n```json\n{\n  \"error\": \"\u8fd9\u4e2a\u4f5c\u54c1\u6570\u636e\u8868\u4e0d\u5141\u8bb8\u516c\u5f00\u5199\u5165\"\n}\n```\n```json\n{\n  \"error\": \"\u516c\u5f00\u63a5\u53e3\u4e0d\u5141\u8bb8\u5220\u9664\u4f5c\u54c1\u6570\u636e\u8868\u3002\"\n}\n```\n\n### HTTP 404\uff1a\u4f5c\u54c1\u3001\u63a5\u53e3\u3001\u6570\u636e\u8868\u6216\u8bb0\u5f55\u4e0d\u5b58\u5728\n\u8bfb\u53d6\u5355\u4e2a\u6570\u636e\u8868\u65f6\u5982\u679c\u8fd4\u56de `404`\uff0c\u53ef\u4ee5\u8ba4\u4e3a\u8fd9\u4e2a\u6570\u636e\u8868\u4e0d\u5b58\u5728\uff0c\u7136\u540e\u521b\u5efa\u5b83\u3002\u4e0d\u8981\u53ea\u5224\u65ad\u82f1\u6587 `not found`\u3002\n```json\n{\n  \"error\": \"\u627e\u4e0d\u5230\u8fd9\u4e2a\u4f5c\u54c1\"\n}\n```\n```json\n{\n  \"error\": \"\u6ca1\u6709\u627e\u5230\u8fd9\u4e2a\u63a5\u53e3\"\n}\n```\n```json\n{\n  \"error\": \"\u627e\u4e0d\u5230\u8fd9\u4e2a\u4f5c\u54c1\u6570\u636e\u8868\"\n}\n```\n```json\n{\n  \"error\": \"\u627e\u4e0d\u5230\u8fd9\u6761\u8bb0\u5f55\"\n}\n```\n\n### HTTP 429\uff1a\u5957\u9910\u989d\u5ea6\u6216\u7528\u91cf\u9650\u5236\n\u5e38\u89c1\u4e8e\u5f53\u524d\u4f5c\u54c1\u8fbe\u5230\u5957\u9910\u5141\u8bb8\u7684\u6570\u636e\u8868\u3001\u8bb0\u5f55\u3001\u8bf7\u6c42\u6b21\u6570\u6216\u5176\u4ed6\u4e92\u52a8\u7528\u91cf\u9650\u5236\u3002\u9047\u5230\u8fd9\u79cd\u9519\u8bef\u65f6\uff0c\u8bf7\u7528\u4e2d\u6587\u63d0\u793a\u7528\u6237\u51cf\u5c11\u64cd\u4f5c\u9891\u7387\u3001\u51cf\u5c11\u6570\u636e\u91cf\u6216\u5347\u7ea7\u5957\u9910\uff0c\u4e0d\u8981\u5faa\u73af\u91cd\u8bd5\u3002\n```json\n{\n  \"error\": \"\u8fd9\u4e2a\u4f5c\u54c1\u672c\u6708\u7684\u4e92\u52a8\u67e5\u8be2\u6b21\u6570\u5df2\u7ecf\u7528\u5b8c\u4e86\"\n}\n```\n```json\n{\n  \"error\": \"\u8fd9\u4e2a\u4f5c\u54c1\u672c\u6708\u7684\u4e92\u52a8\u5199\u5165\u6b21\u6570\u5df2\u7ecf\u7528\u5b8c\u4e86\"\n}\n```\n\n### HTTP 500\uff1a\u670d\u52a1\u5668\u8bfb\u53d6\u6216\u4fdd\u5b58\u5931\u8d25\n\u5e38\u89c1\u4e8e\u5e73\u53f0\u4e34\u65f6\u6545\u969c\u3002\u8bf7\u63d0\u793a\u7528\u6237\u7a0d\u540e\u518d\u8bd5\uff0c\u4e0d\u8981\u5728\u9875\u9762\u91cc\u5c55\u793a\u82f1\u6587\u6280\u672f\u7ec6\u8282\u3002\n```json\n{\n  \"error\": \"\u8bfb\u53d6\u4f5c\u54c1\u6570\u636e\u8868\u5931\u8d25\"\n}\n```\n```json\n{\n  \"error\": \"\u8bfb\u53d6\u8bb0\u5f55\u5931\u8d25\"\n}\n```\n\n## \u63a8\u8350\u7684\u524d\u7aef\u8bf7\u6c42\u5c01\u88c5\n\u8bf7\u4f18\u5148\u4f7f\u7528\u4e0b\u9762\u8fd9\u79cd\u5c01\u88c5\u3002\u5b83\u4f1a\u4fdd\u7559 HTTP \u72b6\u6001\u7801\uff0c\u65b9\u4fbf\u6b63\u786e\u5224\u65ad `404`\u3001`401`\u3001`403`\u3001`429` \u7b49\u9519\u8bef\u3002\n```js\nconst API_BASE = '/api/v1/public/projects/{{PROJECT_ID}}';\nconst PROJECT_KEY = '{{PROJECT_KEY}}';\n\nasync function apiFetch(path, options = {}) {\n  const headers = {\n    'X-Project-Key': PROJECT_KEY,\n    ...(options.headers || {})\n  };\n\n  if (options.body && !headers['Content-Type']) {\n    headers['Content-Type'] = 'application/json';\n  }\n\n  const response = await fetch(`${API_BASE}${path}`, {\n    ...options,\n    headers\n  });\n\n  let data = null;\n  try {\n    data = await response.json();\n  } catch {\n    data = null;\n  }\n\n  if (!response.ok) {\n    const error = new Error(data?.error || `\u8bf7\u6c42\u5931\u8d25\uff0c\u72b6\u6001\u7801\uff1a${response.status}`);\n    error.status = response.status;\n    error.data = data;\n    throw error;\n  }\n\n  return data;\n}\n```\n\n## \u63a8\u8350\u7684\u6570\u636e\u8868\u521d\u59cb\u5316\u65b9\u5f0f\n\u521d\u59cb\u5316\u65f6\u5148\u8bfb\u53d6\u6570\u636e\u8868\uff1b\u53ea\u6709 HTTP `404` \u624d\u521b\u5efa\u6570\u636e\u8868\uff1b\u5176\u4ed6\u9519\u8bef\u8981\u63d0\u793a\u7528\u6237\u6216\u505c\u6b62\u521d\u59cb\u5316\u3002\n```js\nasync function ensureCollection(name, fields) {\n  try {\n    return await apiFetch(`/collections/${encodeURIComponent(name)}`);\n  } catch (error) {\n    // \u6570\u636e\u8868\u4e0d\u5b58\u5728\u65f6\uff0c\u5e73\u53f0\u4f1a\u8fd4\u56de HTTP 404\u3002\u8bf7\u5224\u65ad status\uff0c\u4e0d\u8981\u53ea\u5224\u65ad\u82f1\u6587\u9519\u8bef\u6587\u672c\u3002\n    if (error.status !== 404) {\n      throw error;\n    }\n  }\n\n  return apiFetch('/collections', {\n    method: 'POST',\n    body: JSON.stringify({\n      name,\n      permissions: { publicRead: true, publicWrite: true },\n      fields\n    })\n  });\n}\n\n// \u793a\u4f8b\uff1a\u521d\u59cb\u5316\u5e16\u5b50\u8868\u3002\nawait ensureCollection('posts', [\n  { name: 'title', type: 'string', required: true, isList: false },\n  { name: 'content', type: 'text', required: true, isList: false }\n]);\n```\n\n## \u521b\u5efa\u6570\u636e\u8868\u793a\u4f8b\n\u8fd9\u4e2a\u4f8b\u5b50\u4f1a\u521b\u5efa `posts` \u6570\u636e\u8868\uff0c\u7528\u6765\u4fdd\u5b58\u6807\u9898\u548c\u6b63\u6587\u3002\u5b57\u6bb5\u540d\u5efa\u8bae\u4f7f\u7528\u82f1\u6587\u3001\u62fc\u97f3\u6216\u6570\u5b57\uff0c\u754c\u9762\u6587\u6848\u53ef\u4ee5\u662f\u4e2d\u6587\u3002\n```json\n{\n  \"name\": \"posts\",\n  \"permissions\": {\n    \"publicRead\": true,\n    \"publicWrite\": true\n  },\n  \"fields\": [\n    {\n      \"name\": \"title\",\n      \"type\": \"string\",\n      \"required\": true,\n      \"isList\": false\n    },\n    {\n      \"name\": \"content\",\n      \"type\": \"text\",\n      \"required\": true,\n      \"isList\": false\n    }\n  ]\n}\n```\n\n## \u521b\u5efa\u8bb0\u5f55\u793a\u4f8b\n\u521b\u5efa\u8bb0\u5f55\u65f6\uff0c\u5177\u4f53\u5185\u5bb9\u653e\u5728 `data` \u91cc\u9762\u3002`data` \u91cc\u7684\u5b57\u6bb5\u8981\u548c\u6570\u636e\u8868 `fields` \u4e2d\u5b9a\u4e49\u7684\u5b57\u6bb5\u5bf9\u5e94\u3002\n```json\n{\n  \"data\": {\n    \"title\": \"\u793a\u4f8b\u6807\u9898\",\n    \"content\": \"\u793a\u4f8b\u5185\u5bb9\"\n  }\n}\n```\n\n{{COLLECTIONS_SECTION}}## \u524d\u7aef fetch \u793a\u4f8b\n### \u8bfb\u53d6 posts \u8bb0\u5f55\n```js\napiFetch('/collections/posts/records')\n```\n\n### \u65b0\u589e posts \u8bb0\u5f55\n```js\napiFetch('/collections/posts/records', {\n  method: 'POST',\n  body: JSON.stringify({\n    data: {\n      title: '\u793a\u4f8b\u6807\u9898',\n      content: '\u793a\u4f8b\u5185\u5bb9'\n    }\n  })\n})\n```\n\n### \u521b\u5efa posts \u6570\u636e\u8868\n```js\napiFetch('/collections', {\n  method: 'POST',\n  body: JSON.stringify({\n    name: 'posts',\n    permissions: { publicRead: true, publicWrite: true },\n    fields: [\n      { name: 'title', type: 'string', required: true, isList: false }\n    ]\n  })\n})\n```\n\n## \u7ed9 AI \u7684\u6267\u884c\u8981\u6c42\n- \u5148\u6839\u636e\u7528\u6237\u60f3\u8981\u7684\u4e92\u52a8\u6548\u679c\u8bbe\u8ba1\u6570\u636e\u8868\uff0c\u4f8b\u5982 `comments`\u3001`messages`\u3001`posts`\u3001`profiles`\u3001`saves`\u3002\n- \u5982\u679c\u73b0\u6709\u6570\u636e\u8868\u5df2\u7ecf\u6ee1\u8db3\u9700\u6c42\uff0c\u76f4\u63a5\u590d\u7528\uff0c\u4e0d\u8981\u91cd\u590d\u521b\u5efa\u540c\u540d\u6570\u636e\u8868\u3002\n- \u4e0d\u8981\u8c03\u7528\u6216\u7f16\u5199\u5220\u9664\u6570\u636e\u8868\u7684\u903b\u8f91\u3002\u4e92\u52a8\u4f5c\u54c1\u91cc\u7684\u516c\u5f00 key \u53ea\u7528\u4e8e\u81ea\u52a8\u521b\u5efa\u5fc5\u8981\u6570\u636e\u8868\u548c\u8bfb\u5199\u8bb0\u5f55\uff0c\u4e0d\u7528\u4e8e\u7834\u574f\u6027\u8868\u7ba1\u7406\u3002\n- \u4e0d\u8981\u6839\u636e\u82f1\u6587\u9519\u8bef\u6587\u672c\u5224\u65ad\u4e1a\u52a1\u903b\u8f91\uff1b\u8bf7\u4f7f\u7528 `error.status` \u6216 `response.status`\u3002\n- \u5199\u4ee3\u7801\u65f6\u8981\u5904\u7406\u7f51\u7edc\u5931\u8d25\u3001\u63a5\u53e3\u8fd4\u56de\u9519\u8bef\u548c\u7a7a\u6570\u636e\u72b6\u6001\uff0c\u5e76\u7528\u4e2d\u6587\u63d0\u793a\u7528\u6237\u3002\n- \u751f\u6210\u9875\u9762\u65f6\u8981\u4fdd\u8bc1\u6309\u94ae\u3001\u8f93\u5165\u6846\u3001\u6587\u672c\u6846\u6709\u6e05\u6670\u4e2d\u6587\u6807\u7b7e\uff0c\u952e\u76d8\u4e5f\u80fd\u64cd\u4f5c\u3002"

func (rt *Router) handleProjectInteractiveDoc(w http.ResponseWriter, r *http.Request, projectID string) {
	_, project, ok := rt.requireOwnedProject(w, r, projectID)
	if !ok {
		return
	}
	if !project.Interactive {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "\u8fd9\u4e2a\u4f5c\u54c1\u8fd8\u6ca1\u6709\u542f\u7528\u4e92\u52a8\u529f\u80fd"})
		return
	}

	_ = rt.ensureProjectLiveLink(r.Context(), project)

	projectKey := rt.lookupProjectPublicKey(r.Context(), projectID)
	if strings.TrimSpace(projectKey) == "" {
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "\u751f\u6210\u4e92\u52a8 API \u6587\u6863\u5931\u8d25"})
		return
	}

	collections, err := rt.store.ListCollections(r.Context(), project.ID)
	if err != nil {
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "\u8bfb\u53d6\u4f5c\u54c1\u6570\u636e\u8868\u5931\u8d25"})
		return
	}

	writeJSON(w, http.StatusOK, map[string]string{
		"doc": buildInteractiveAPIDoc(project, projectKey, collections),
	})
}

func buildInteractiveAPIDoc(project domain.Project, projectKey string, collections []domain.Collection) string {
	doc := interactiveDocTemplate
	doc = strings.ReplaceAll(doc, "{{PROJECT_ID}}", project.ID)
	doc = strings.ReplaceAll(doc, "{{PROJECT_NAME}}", project.Name)
	doc = strings.ReplaceAll(doc, "{{PUBLIC_URL}}", project.PublicURL)
	doc = strings.ReplaceAll(doc, "{{PROJECT_KEY}}", projectKey)
	doc = strings.ReplaceAll(doc, "{{COLLECTIONS_SECTION}}", buildInteractiveCollectionsSection(collections))
	return doc
}

func buildInteractiveCollectionsSection(collections []domain.Collection) string {
	var lines []string
	lines = append(lines, "## \u73b0\u6709\u6570\u636e\u8868")
	if len(collections) == 0 {
		lines = append(lines, "\u6682\u65f6\u6ca1\u6709\u6570\u636e\u8868\u3002\u5982\u679c\u9700\u8981\u4fdd\u5b58\u6570\u636e\uff0c\u8bf7\u5148\u8c03\u7528\u521b\u5efa\u6570\u636e\u8868\u63a5\u53e3\u3002", "")
		return strings.Join(lines, "\n") + "\n"
	}

	for _, collection := range collections {
		lines = append(lines, "### "+collection.Name)
		lines = append(lines, fmt.Sprintf("- publicRead\uff1a%s", interactiveDocYesNo(collection.Permissions.PublicRead)))
		lines = append(lines, fmt.Sprintf("- publicWrite\uff1a%s", interactiveDocYesNo(collection.Permissions.PublicWrite)))
		if len(collection.Fields) == 0 {
			lines = append(lines, "- \u5b57\u6bb5\uff1a\u6682\u65e0")
		} else {
			lines = append(lines, "- \u5b57\u6bb5\uff1a")
			for _, field := range collection.Fields {
				reference := ""
				if field.Reference != "" {
					reference = "\uff0c\u5173\u8054\u6570\u636e\u8868\uff1a" + field.Reference
				}
				lines = append(lines, fmt.Sprintf("  - %s\uff1a\u7c7b\u578b %s\uff0c\u5fc5\u586b %s\uff0c\u591a\u503c %s%s", field.Name, field.Type, interactiveDocYesNo(field.Required), interactiveDocYesNo(field.IsList), reference))
			}
		}
		lines = append(lines, "")
	}
	return strings.Join(lines, "\n") + "\n"
}

func interactiveDocYesNo(value bool) string {
	if value {
		return "\u662f"
	}
	return "\u5426"
}
